#!/usr/bin/env python3
import sys, os, re, json, math, csv, io
from dataclasses import dataclass
from datetime import datetime, timezone, timedelta
from collections import OrderedDict, defaultdict

VERSION = "ag 0.19.6"

HELP_LONG = """Usage: executable [OPTIONS] [QUERY]

Arguments:
  [QUERY]
          The query

Options:
  -f, --file <FILE>
          Optionally reads from a file instead of Stdin

  -m, --format <FORMAT>
          DEPRECATED. Use -o format=... instead. Provide a Rust std::fmt string to format output

  -o, --output <OUTPUT>
          Set output format. Options: 
          - `json`,
          - `logfmt`
          - `format=<rust format string>` (eg. -o format='{src} => {dst}'
          - `legacy` The original output format, auto aligning [k=v]

  -a, --alias-dir <ALIAS_DIR>
          Specifies an alternative directory to use for aliases. Defaults to `.agrind-aliases` in all parent directories.

      --no-alias
          Disables aliases

  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version

For more details + docs, see https://github.com/rcoh/angle-grinder
"""

HELP_SHORT = """Usage: executable [OPTIONS] [QUERY]

Arguments:
  [QUERY]  The query

Options:
  -f, --file <FILE>            Optionally reads from a file instead of Stdin
  -m, --format <FORMAT>        DEPRECATED. Use -o format=... instead. Provide a Rust std::fmt string to format output
  -o, --output <OUTPUT>        Set output format. One of (json|legacy|format=<rust fmt str>|logfmt)
  -a, --alias-dir <ALIAS_DIR>  Specifies an alternative directory to use for aliases. Defaults to `.agrind-aliases` in all parent directories.
      --no-alias               Disables aliases
  -h, --help                   Print help (see more with '--help')
  -V, --version                Print version

For more details + docs, see https://github.com/rcoh/angle-grinder
"""


def eprint(*args, **kwargs):
    print(*args, file=sys.stderr, **kwargs)

@dataclass
class DateVal:
    dt: datetime
    def __post_init__(self):
        if self.dt.tzinfo is None:
            self.dt = self.dt.replace(tzinfo=timezone.utc)
        else:
            self.dt = self.dt.astimezone(timezone.utc)
    def legacy(self):
        return self.dt.strftime("%Y-%m-%d %H:%M:%S UTC")
    def json(self):
        return self.dt.isoformat(timespec='seconds')

class EvalError(Exception):
    pass

class ParseError(Exception):
    pass

class Record:
    __slots__ = ("raw", "fields", "raw_if_empty")
    def __init__(self, raw="", fields=None, raw_if_empty=True):
        self.raw = raw
        self.fields = dict(fields or {})
        self.raw_if_empty = raw_if_empty
    def copy(self):
        return Record(self.raw, dict(self.fields), self.raw_if_empty)

# ---------------- value formatting ----------------

def is_num(v):
    return (isinstance(v, (int, float)) and not isinstance(v, bool))

def to_number(v):
    if is_num(v):
        return v
    if isinstance(v, str):
        s = v.strip()
        try:
            if re.fullmatch(r'[+-]?\d+', s):
                return int(s)
            if re.fullmatch(r'[+-]?(?:\d+\.\d*|\d*\.\d+)(?:[eE][+-]?\d+)?|[+-]?\d+[eE][+-]?\d+', s):
                return float(s)
        except Exception:
            pass
    raise EvalError(f"Expected number, found {legacy_value(v)}")

def maybe_number(v):
    try:
        return to_number(v)
    except Exception:
        return None

def auto_convert(s):
    if not isinstance(s, str):
        return s
    st = s.strip()
    if st == "true":
        return True
    if st == "false":
        return False
    # The original does not convert textual null/None to null.
    if re.fullmatch(r'[+-]?\d+', st):
        try:
            return int(st)
        except Exception:
            return s
    if re.fullmatch(r'[+-]?(?:\d+\.\d*|\d*\.\d+)(?:[eE][+-]?\d+)?|[+-]?\d+[eE][+-]?\d+', st):
        try:
            return float(st)
        except Exception:
            return s
    return s

def legacy_value(v):
    if isinstance(v, DateVal):
        return v.legacy()
    if v is None:
        return "None"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int) and not isinstance(v, bool):
        return str(v)
    if isinstance(v, float):
        if math.isnan(v):
            return "NaN"
        if math.isinf(v):
            return "inf" if v > 0 else "-inf"
        if abs(v) == 0:
            return "0"
        if float(v).is_integer():
            return str(int(v))
        return f"{v:.2f}"
    if isinstance(v, list):
        return "[" + ", ".join(legacy_value(x) for x in v) + "]"
    if isinstance(v, dict):
        parts = []
        for k in sorted(v.keys(), key=str):
            parts.append(f"{k}:{legacy_value(v[k])}")
        return "{" + ", ".join(parts) + "}"
    return str(v)

def jsonable(v):
    if isinstance(v, DateVal):
        return v.json()
    if isinstance(v, float):
        if math.isnan(v) or math.isinf(v):
            return None
        if abs(v) == 0:
            return 0
        if v.is_integer():
            return int(v)
        return v
    if isinstance(v, list):
        return [jsonable(x) for x in v]
    if isinstance(v, dict):
        return OrderedDict((k, jsonable(v[k])) for k in sorted(v.keys(), key=str))
    return v

def dumps_json_obj(mapping, key_order=None):
    if key_order is None:
        keys = sorted(mapping.keys(), key=str)
    else:
        keys = [k for k in key_order if k in mapping]
        keys += [k for k in sorted(mapping.keys(), key=str) if k not in keys]
    od = OrderedDict((k, jsonable(mapping[k])) for k in keys)
    return json.dumps(od, separators=(',', ':'), ensure_ascii=False)

# ---------------- string splitting helpers ----------------

def split_top_level(s, sep=','):
    out=[]; cur=[]; depth=0; in_str=False; esc=False; br_depth=0
    for ch in s:
        if in_str:
            cur.append(ch)
            if esc:
                esc=False
            elif ch == '\\':
                esc=True
            elif ch == '"':
                in_str=False
            continue
        if ch == '"':
            in_str=True; cur.append(ch); continue
        if ch in '([{':
            depth += 1
        elif ch in ')]}':
            depth = max(0, depth-1)
        if ch == sep and depth == 0:
            out.append(''.join(cur).strip()); cur=[]
        else:
            cur.append(ch)
    out.append(''.join(cur).strip())
    return out

def split_pipeline(query):
    return split_top_level(query, '|')

def find_top_level_word(s, word):
    # returns (start,end) for first standalone word outside syntax
    depth=0; in_str=False; esc=False; i=0; lw=word.lower(); n=len(s)
    while i<n:
        ch=s[i]
        if in_str:
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch=='"': in_str=False
            i+=1; continue
        if ch=='"': in_str=True; i+=1; continue
        if ch in '([{': depth+=1
        elif ch in ')]}': depth=max(0,depth-1)
        if depth==0 and s[i:i+len(word)].lower()==lw:
            before = s[i-1] if i>0 else ' '
            after = s[i+len(word)] if i+len(word)<n else ' '
            if (not (before.isalnum() or before=='_')) and (not (after.isalnum() or after=='_')):
                return (i,i+len(word))
        i+=1
    return None

def split_as(s):
    # last top-level 'as'
    depth=0; in_str=False; esc=False; positions=[]; i=0; n=len(s)
    while i<n:
        ch=s[i]
        if in_str:
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch=='"': in_str=False
            i+=1; continue
        if ch=='"': in_str=True; i+=1; continue
        if ch in '([{': depth+=1
        elif ch in ')]}': depth=max(0,depth-1)
        if depth==0 and s[i:i+2].lower()=='as':
            before=s[i-1] if i>0 else ' '
            after=s[i+2] if i+2<n else ' '
            if before.isspace() and after.isspace():
                positions.append((i,i+2))
        i+=1
    if not positions:
        return (s.strip(), None)
    st,en=positions[-1]
    return (s[:st].strip(), s[en:].strip())

def unquote(s):
    s=s.strip()
    if len(s)>=2 and s[0]=='"' and s[-1]=='"':
        out=[]; esc=False
        for ch in s[1:-1]:
            if esc:
                if ch=='n': out.append('\n')
                elif ch=='t': out.append('\t')
                else: out.append(ch)
                esc=False
            elif ch=='\\': esc=True
            else: out.append(ch)
        if esc: out.append('\\')
        return ''.join(out)
    return s

def parse_field_name(name):
    name=name.strip()
    if name.startswith('["'):
        if not name.endswith(']'):
            raise ParseError("unterminated identifier")
        return unquote(name[1:-1])
    return name

# ---------------- filter parser ----------------

@dataclass
class FilterTerm:
    text: str
    quoted: bool=False
    def match(self,line):
        if not self.quoted and self.text == '*':
            return True
        if self.quoted:
            return self.text in line
        pat = ''.join('.*' if c=='*' else re.escape(c) for c in self.text)
        try:
            return re.search(pat, line, re.IGNORECASE) is not None
        except re.error:
            return self.text.lower() in line.lower()
@dataclass
class FilterNot:
    a: object
    def match(self,line): return not self.a.match(line)
@dataclass
class FilterBin:
    op: str; a: object; b: object
    def match(self,line):
        return (self.a.match(line) and self.b.match(line)) if self.op=='AND' else (self.a.match(line) or self.b.match(line))

class FilterParser:
    def __init__(self,s):
        self.tokens=self.lex(s); self.i=0
    def lex(self,s):
        toks=[]; i=0; n=len(s)
        while i<n:
            if s[i].isspace(): i+=1; continue
            if s[i] in '()': toks.append((s[i],s[i])); i+=1; continue
            if s[i]=='"':
                j=i+1; esc=False; val=[]
                while j<n:
                    ch=s[j]
                    if esc:
                        val.append(ch); esc=False
                    elif ch=='\\': esc=True
                    elif ch=='"': break
                    else: val.append(ch)
                    j+=1
                toks.append(('Q',''.join(val))); i=(j+1 if j<n else j); continue
            j=i
            while j<n and (not s[j].isspace()) and s[j] not in '()': j+=1
            word=s[i:j]
            up=word.upper()
            if up in ('AND','OR','NOT'): toks.append((up,up))
            else: toks.append(('TERM',word))
            i=j
        return toks
    def peek(self): return self.tokens[self.i] if self.i<len(self.tokens) else None
    def eat(self,t=None):
        tok=self.peek()
        if tok is None or (t is not None and tok[0]!=t): return None
        self.i+=1; return tok
    def parse(self): return self.parse_or() if self.tokens else FilterTerm('*')
    def parse_or(self):
        node=self.parse_and()
        while self.eat('OR'):
            node=FilterBin('OR', node, self.parse_and())
        return node
    def parse_and(self):
        node=self.parse_not()
        while self.eat('AND'):
            node=FilterBin('AND', node, self.parse_not())
        return node
    def parse_not(self):
        if self.eat('NOT'): return FilterNot(self.parse_not())
        return self.parse_primary()
    def parse_primary(self):
        if self.eat('('):
            node=self.parse_or(); self.eat(')'); return node
        tok=self.eat('Q')
        if tok: return FilterTerm(tok[1], True)
        tok=self.eat('TERM')
        if tok: return FilterTerm(tok[1], False)
        return FilterTerm('*')

