@dataclass
class Literal:
    value: object
    def eval(self, rec, ctx): return self.value
@dataclass
class FieldRef:
    parts: list
    text: str
    def eval(self, rec, ctx):
        cur = rec.fields
        top = self.parts[0]
        if top not in cur:
            if ctx.get('missing_none'):
                return None
            raise EvalError(f'No value for key "{self.text}"')
        cur = cur[top]
        for p in self.parts[1:]:
            if isinstance(p, int):
                if isinstance(cur, list):
                    idx=p if p>=0 else len(cur)+p
                    if idx < 0 or idx >= len(cur):
                        if ctx.get('missing_none'): return None
                        raise EvalError(f'Index {p} out of range')
                    cur=cur[idx]
                else:
                    if ctx.get('missing_none'): return None
                    raise EvalError(f'Cannot index {legacy_value(cur)}')
            else:
                if isinstance(cur, dict) and p in cur:
                    cur=cur[p]
                else:
                    if ctx.get('missing_none'): return None
                    raise EvalError(f'No value for key "{self.text}"')
        return cur
@dataclass
class Unary:
    op: str; a: object
    def eval(self, rec, ctx):
        v=self.a.eval(rec,ctx)
        if self.op=='!': return not truthy(v)
        if self.op=='-':
            try: return -to_number(v)
            except EvalError as e: raise e
        return v
@dataclass
class Binary:
    op: str; a: object; b: object
    def eval(self, rec, ctx):
        if self.op in ('and','&&'):
            av=self.a.eval(rec,ctx)
            return self.b.eval(rec,ctx) if truthy(av) else False
        if self.op in ('or','||'):
            av=self.a.eval(rec,ctx)
            return True if truthy(av) else self.b.eval(rec,ctx)
        av=self.a.eval(rec,ctx); bv=self.b.eval(rec,ctx)
        if self.op in ('+','-','*','/'):
            if isinstance(av, DateVal) and isinstance(bv, DateVal) and self.op=='-':
                return (av.dt-bv.dt).total_seconds()
            try:
                an=to_number(av); bn=to_number(bv)
            except EvalError:
                raise EvalError(f"Expected numeric operands, found {legacy_value(av)} {self.op} {legacy_value(bv)}")
            if self.op=='+': return an+bn
            if self.op=='-': return an-bn
            if self.op=='*': return an*bn
            if self.op=='/': return an/bn
        if self.op in ('==','!=','<>','<','>','<=','>='):
            c=cmp_values(av,bv)
            if self.op=='==': return c==0
            if self.op in ('!=','<>'): return c!=0
            if self.op=='<': return c<0
            if self.op=='>': return c>0
            if self.op=='<=': return c<=0
            if self.op=='>=': return c>=0
        return None
@dataclass
class FuncCall:
    name: str; args: list
    def eval(self, rec, ctx):
        nm=self.name
        if nm == 'if':
            if len(self.args)!=3: return None
            return self.args[1].eval(rec,ctx) if truthy(self.args[0].eval(rec,ctx)) else self.args[2].eval(rec,ctx)
        vals=[a.eval(rec,ctx) for a in self.args]
        return call_func(nm, vals)

def truthy(v):
    if v is None: return False
    if isinstance(v, bool): return v
    if is_num(v): return v != 0 and not (isinstance(v,float) and math.isnan(v))
    if isinstance(v, str): return len(v) > 0
    return True

def type_rank(v):
    if v is None: return 0
    if isinstance(v,bool): return 1
    if is_num(v): return 2
    if isinstance(v, DateVal): return 2.5
    if isinstance(v,str): return 3
    if isinstance(v,list): return 4
    if isinstance(v,dict): return 5
    return 6

def cmp_values(a,b):
    # Equality is strict by type (except int/float share number class); ordering follows value type order.
    if is_num(a) and is_num(b):
        af=float(a); bf=float(b)
        if math.isnan(af) and math.isnan(bf): return 0
        if math.isnan(af): return 1
        if math.isnan(bf): return -1
        return (af>bf)-(af<bf)
    if isinstance(a, DateVal) and isinstance(b, DateVal):
        return (a.dt>b.dt)-(a.dt<b.dt)
    if type(a) is type(b) and isinstance(a,(str,bool)):
        return (a>b)-(a<b)
    if a is None and b is None: return 0
    ra=type_rank(a); rb=type_rank(b)
    if ra != rb: return (ra>rb)-(ra<rb)
    sa=legacy_value(a); sb=legacy_value(b)
    return (sa>sb)-(sa<sb)

def call_func(name, vals):
    math_funcs = {
        'abs': abs, 'acos': math.acos, 'asin': math.asin, 'atan': math.atan,
        'cbrt': lambda x: math.copysign(abs(x)**(1.0/3.0), x), 'ceil': math.ceil,
        'cos': math.cos, 'cosh': math.cosh, 'exp': math.exp, 'expm1': math.expm1,
        'floor': math.floor, 'log': math.log, 'log10': math.log10, 'log1p': math.log1p,
        'round': round, 'sin': math.sin, 'sinh': math.sinh, 'sqrt': math.sqrt,
        'tan': math.tan, 'tanh': math.tanh, 'toDegrees': math.degrees, 'toRadians': math.radians,
    }
    if name in ('atan2','hypot'):
        a=to_number(vals[0]); b=to_number(vals[1]); return math.atan2(a,b) if name=='atan2' else math.hypot(a,b)
    if name in math_funcs:
        return math_funcs[name](to_number(vals[0]))
    if name == 'concat':
        return ''.join(legacy_value(v) if v is not None else 'None' for v in vals)
    if name == 'contains':
        return str(vals[0]).find(str(vals[1])) >= 0
    if name == 'length':
        return len(str(vals[0])) if not isinstance(vals[0], (list,dict)) else len(vals[0])
    if name == 'now':
        return DateVal(datetime.now(timezone.utc))
    if name == 'num':
        return to_number(vals[0])
    if name == 'parseDate':
        return parse_date(str(vals[0]))
    if name == 'parseHex':
        s=str(vals[0]).strip()
        if s.startswith(('0x','0X')): s=s[2:]
        return int(s,16)
    if name == 'substring':
        s=str(vals[0]); start=int(to_number(vals[1]));
        if len(vals)>=3: return s[start:int(to_number(vals[2]))]
        return s[start:]
    if name == 'toLowerCase': return str(vals[0]).lower()
    if name == 'toUpperCase': return str(vals[0]).upper()
    if name == 'isNull': return vals[0] is None
    if name == 'isEmpty': return vals[0] is None or str(vals[0]) == ''
    if name == 'isBlank': return vals[0] is None or str(vals[0]).strip() == ''
    if name == 'isNumeric': return maybe_number(vals[0]) is not None
    return None

def parse_date(s):
    st=s.strip()
    # Normalize ISO Z suffix.
    tries=[]
    if st.endswith('Z'):
        tries.append(st[:-1] + '+00:00')
    tries.append(st)
    fmts=['%Y-%m-%d %H:%M:%S','%Y-%m-%dT%H:%M:%S','%Y-%m-%d','%Y/%m/%d %H:%M:%S']
    for t in tries:
        try:
            return DateVal(datetime.fromisoformat(t))
        except Exception:
            pass
    for fmt in fmts:
        try:
            return DateVal(datetime.strptime(st, fmt).replace(tzinfo=timezone.utc))
        except Exception:
            pass
    raise EvalError(f"Could not parse date {s}")

class ExprParser:
    def __init__(self,s):
        self.s=s; self.tokens=self.lex(s); self.i=0
    def lex(self,s):
        toks=[]; i=0; n=len(s)
        prev_can_end=False
        while i<n:
            ch=s[i]
            if ch.isspace(): i+=1; continue
            if ch=='"':
                j=i+1; esc=False; val=[]
                while j<n:
                    c=s[j]
                    if esc:
                        if c=='n': val.append('\n')
                        elif c=='t': val.append('\t')
                        else: val.append(c)
                        esc=False
                    elif c=='\\': esc=True
                    elif c=='"': break
                    else: val.append(c)
                    j+=1
                toks.append(('STR',''.join(val))); i=(j+1 if j<n else j); prev_can_end=True; continue
            if ch=='[' and i+1<n and s[i+1]=='"':
                # escaped field identifier ["..."]
                j=i+2; esc=False; val=[]
                while j<n:
                    c=s[j]
                    if esc:
                        val.append(c); esc=False
                    elif c=='\\': esc=True
                    elif c=='"':
                        if j+1<n and s[j+1]==']':
                            j+=1; break
                        else:
                            val.append(c)
                    else: val.append(c)
                    j+=1
                toks.append(('IDENT',''.join(val))); i=j+1; prev_can_end=True; continue
            two=s[i:i+2]
            if two in ('==','!=','<=','>=','<>','&&','||'):
                toks.append(('OP',two)); i+=2; prev_can_end=False; continue
            if ch in '+-*/(),.[]<>!':
                toks.append(('OP',ch)); i+=1; prev_can_end=(ch in ')]'); continue
            if ch.isdigit() or (ch=='.' and i+1<n and s[i+1].isdigit()):
                j=i
                while j<n and (s[j].isdigit() or s[j] in '.eE+-' and j>i and s[j-1] in 'eE'):
                    j+=1
                txt=s[i:j]
                try:
                    val=float(txt) if any(c in txt for c in '.eE') else int(txt)
                except Exception:
                    val=0
                toks.append(('NUM',val)); i=j; prev_can_end=True; continue
            # identifier: allow many field-name chars until operator/space
            j=i
            while j<n and (not s[j].isspace()) and s[j] not in '+-*/(),[]<>!=':
                # stop dot as separate only for normal path
                if s[j]=='.': break
                j+=1
            word=s[i:j]
            if not word and s[j]=='.':
                toks.append(('OP','.')); i=j+1; prev_can_end=False; continue
            lw=word.lower()
            if lw in ('and','or'):
                toks.append(('OP',lw)); prev_can_end=False
            elif lw=='true': toks.append(('BOOL',True)); prev_can_end=True
            elif lw=='false': toks.append(('BOOL',False)); prev_can_end=True
            elif lw in ('null','none'): toks.append(('NULL',None)); prev_can_end=True
            else: toks.append(('IDENT',word)); prev_can_end=True
            i=j
        return toks
    def peek(self): return self.tokens[self.i] if self.i<len(self.tokens) else None
    def eat(self,typ=None,val=None):
        tok=self.peek()
        if tok is None: return None
        if typ is not None and tok[0]!=typ: return None
        if val is not None and tok[1]!=val: return None
        self.i+=1; return tok
    def parse(self):
        if not self.tokens: return Literal(None)
        return self.parse_or()
    def parse_or(self):
        node=self.parse_and()
        while True:
            tok=self.peek()
            if tok and tok[0]=='OP' and tok[1] in ('or','||'):
                self.i+=1; node=Binary(tok[1],node,self.parse_and())
            else: break
        return node
    def parse_and(self):
        node=self.parse_cmp()
        while True:
            tok=self.peek()
            if tok and tok[0]=='OP' and tok[1] in ('and','&&'):
                self.i+=1; node=Binary(tok[1],node,self.parse_cmp())
            else: break
        return node
    def parse_cmp(self):
        node=self.parse_add()
        while True:
            tok=self.peek()
            if tok and tok[0]=='OP' and tok[1] in ('==','!=','<>','<','>','<=','>='):
                self.i+=1; node=Binary(tok[1],node,self.parse_add())
            else: break
        return node
    def parse_add(self):
        node=self.parse_mul()
        while True:
            tok=self.peek()
            if tok and tok[0]=='OP' and tok[1] in ('+','-'):
                self.i+=1; node=Binary(tok[1],node,self.parse_mul())
            else: break
        return node
    def parse_mul(self):
        node=self.parse_unary()
        while True:
            tok=self.peek()
            if tok and tok[0]=='OP' and tok[1] in ('*','/'):
                self.i+=1; node=Binary(tok[1],node,self.parse_unary())
            else: break
        return node
    def parse_unary(self):
        tok=self.peek()
        if tok and tok[0]=='OP' and tok[1] in ('!','-'):
            self.i+=1; return Unary(tok[1], self.parse_unary())
        return self.parse_primary()
    def parse_primary(self):
        tok=self.peek()
        if tok is None: return Literal(None)
        if self.eat('OP','('):
            node=self.parse_or(); self.eat('OP',')'); return node
        tok=self.eat('NUM')
        if tok: return Literal(tok[1])
        tok=self.eat('STR')
        if tok: return Literal(tok[1])
        tok=self.eat('BOOL')
        if tok: return Literal(tok[1])
        tok=self.eat('NULL')
        if tok: return Literal(None)
        tok=self.eat('IDENT')
        if tok:
            name=tok[1]
            if self.eat('OP','('):
                args=[]
                if not self.eat('OP',')'):
                    while True:
                        args.append(self.parse_or())
                        if self.eat('OP',','): continue
                        self.eat('OP',')'); break
                return FuncCall(name,args)
            parts=[name]; text=name
            while True:
                if self.eat('OP','.'):
                    t=self.eat('IDENT')
                    if t:
                        parts.append(t[1]); text += '.'+t[1]
                elif self.eat('OP','['):
                    sign=1
                    if self.eat('OP','-'): sign=-1
                    num=self.eat('NUM')
                    idx=0 if not num else int(num[1])*sign
                    self.eat('OP',']')
                    parts.append(idx); text += f'[{idx}]'
                else: break
            return FieldRef(parts,text)
        # Unknown token -> null literal
        self.i+=1
        return Literal(None)

