def op_json(records, from_field=None):
    out=[]
    for r in records:
        if from_field:
            if from_field not in r.fields:
                eprint(f'error: No value for key "{from_field}"'); continue
            src=r.fields[from_field]
            if not isinstance(src,str):
                eprint('error: Expected string, found other'); continue
        else:
            src=r.raw
        try:
            val=json.loads(src)
        except Exception:
            eprint(f'error: Expected JSON, found {src}'); continue
        nr=r.copy()
        if isinstance(val,dict):
            for k in sorted(val.keys(), key=str):
                nr.fields[k]=val[k]
            if val:
                nr.raw_if_empty=False
        # non-object JSON keeps the row otherwise unchanged.
        out.append(nr)
    return out

def parse_logfmt_line(s):
    res={}
    if s.strip()=="":
        return {"": None}
    i=0; n=len(s)
    while i<n:
        while i<n and s[i].isspace(): i+=1
        if i>=n: break
        # key up to = or whitespace
        kstart=i
        while i<n and (not s[i].isspace()) and s[i] != '=':
            i+=1
        key=s[kstart:i]
        val=None
        if i<n and s[i]=='=':
            i+=1
            if i<n and s[i]=='"':
                i+=1; chars=[]; esc=False
                while i<n:
                    c=s[i]
                    if esc:
                        chars.append(c); esc=False
                    elif c=='\\': esc=True
                    elif c=='"':
                        i+=1; break
                    else: chars.append(c)
                    i+=1
                val=''.join(chars)
            else:
                vstart=i
                while i<n and not s[i].isspace(): i+=1
                val=s[vstart:i]
                # A token key= followed by whitespace gets the next bare word as its value.
                if val=='' and i<n:
                    j=i
                    while j<n and s[j].isspace(): j+=1
                    k=j
                    while k<n and not s[k].isspace(): k+=1
                    nxt=s[j:k]
                    if nxt and '=' not in nxt:
                        val=nxt; i=k
        if key != '' or val is None:
            res[key]=auto_convert(val) if val is not None else None
        # ignore malformed =value tokens with empty key and explicit value
    return res

def op_logfmt(records, from_field=None):
    out=[]
    for r in records:
        if from_field:
            if from_field not in r.fields:
                eprint(f'error: No value for key "{from_field}"'); continue
            src=r.fields[from_field]
            if not isinstance(src,str):
                eprint('error: Expected string, found other'); continue
        else:
            src=r.raw
        fields=parse_logfmt_line(src)
        nr=r.copy()
        for k in sorted(fields.keys(), key=str):
            nr.fields[k]=fields[k]
        if fields:
            nr.raw_if_empty=False
        out.append(nr)
    return out

def pattern_to_regex(pat):
    # Whitespace in the pattern matches arbitrary whitespace; '*' captures non-greedily except final star.
    parts=[]; stars=0; i=0; n=len(pat)
    while i<n:
        if pat[i]=='*':
            stars += 1
            # Final star captures to the end; intermediate captures minimal.
            if pat.find('*', i+1) == -1:
                parts.append('(.*)')
            else:
                parts.append('(.*?)')
            i+=1
        elif pat[i].isspace():
            while i<n and pat[i].isspace(): i+=1
            parts.append(r'\s+')
        else:
            j=i
            while j<n and pat[j] != '*' and not pat[j].isspace(): j+=1
            parts.append(re.escape(pat[i:j])); i=j
    return re.compile(''.join(parts), re.DOTALL), stars

def op_parse(records, spec):
    # parse "pattern" [from field] as a,b [nodrop] [noconvert]
    m=re.match(r'parse\s+"((?:\\.|[^"])*)"\s*(.*)$', spec, re.I|re.S)
    if not m:
        raise ParseError('Invalid parse')
    pattern=unquote('"'+m.group(1)+'"'); rest=m.group(2).strip()
    from_field=None; nodrop=False; noconvert=False
    if rest.lower().startswith('from '):
        # field until ' as '
        pos=find_top_level_word(rest, 'as')
        if not pos: raise ParseError('Invalid parse')
        from_field=rest[5:pos[0]].strip(); rest=rest[pos[1]:].strip()
    if not rest.lower().startswith('as '):
        raise ParseError('Invalid parse')
    rest=rest[3:].strip()
    flags=[]
    # split names from flags; flags are words nodrop/noconvert at end
    words=rest.split()
    while words and words[-1].lower() in ('nodrop','noconvert'):
        flags.append(words.pop().lower())
    name_part=' '.join(words)
    nodrop='nodrop' in flags; noconvert='noconvert' in flags
    names=[parse_field_name(x.strip()) for x in split_top_level(name_part, ',') if x.strip()]
    rgx, star_count=pattern_to_regex(pattern)
    if star_count != len(names):
        raise ParseError(f'Wrong number of patterns for parse. Pattern has {star_count} but {len(names)} were extracted')
    out=[]
    for r in records:
        if from_field:
            if from_field not in r.fields:
                eprint(f'error: No value for key "{from_field}"'); continue
            src=r.fields[from_field]
            if not isinstance(src,str): src=legacy_value(src)
        else:
            src=r.raw
        mm=rgx.search(src)
        nr=r.copy()
        if not mm:
            if nodrop:
                for nm in names: nr.fields[nm]=None
                nr.raw_if_empty=False; out.append(nr)
            continue
        for nm,val in zip(names, mm.groups()):
            nr.fields[nm]=val if noconvert else auto_convert(val.strip())
        nr.raw_if_empty=False; out.append(nr)
    return out

def op_parse_regex(records, spec):
    m=re.match(r'parse\s+regex\s+"((?:\\.|[^"])*)"\s*(.*)$', spec, re.I|re.S)
    if not m: raise ParseError('Invalid parse regex')
    pattern=unquote('"'+m.group(1)+'"'); rest=m.group(2).strip()
    # detect unnamed captures approximately
    unnamed=0; esc=False; in_class=False
    for i,ch in enumerate(pattern):
        if esc: esc=False; continue
        if ch=='\\': esc=True; continue
        if ch=='[': in_class=True
        elif ch==']': in_class=False
        elif ch=='(' and not in_class:
            nxt=pattern[i+1:i+3]
            if pattern[i+1:i+3] != '?:' and pattern[i+1:i+4] != '?P<':
                unnamed += 1
    if unnamed:
        raise ParseError('regular expression for the parse operator cannot have unnamed captures')
    from_field=None; nodrop=False
    # parse optional from and nodrop in either order used by docs
    if ' nodrop' in (' '+rest.lower()):
        nodrop=True
        rest=re.sub(r'\bnodrop\b','',rest,flags=re.I).strip()
    if rest.lower().startswith('from '):
        from_field=rest[5:].strip()
    rgx=re.compile(pattern)
    names=list(rgx.groupindex.keys())
    out=[]
    for r in records:
        if from_field:
            if from_field not in r.fields:
                eprint(f'error: No value for key "{from_field}"'); continue
            src=r.fields[from_field]
            if not isinstance(src,str): src=legacy_value(src)
        else:
            src=r.raw
        mm=rgx.search(src)
        nr=r.copy()
        if not mm:
            if nodrop:
                for nm in names: nr.fields[nm]=None
                nr.raw_if_empty=False; out.append(nr)
            continue
        for nm in names:
            nr.fields[nm]=auto_convert(mm.group(nm).strip())
        nr.raw_if_empty=False; out.append(nr)
    return out

def split_csvish(src, sep):
    try:
        row=next(csv.reader([src], delimiter=sep, quotechar='"', skipinitialspace=True))
    except Exception:
        row=src.split(sep)
    vals=[]
    for x in row:
        y=x.strip()
        if y=='':
            continue
        vals.append(auto_convert(y) if False else y)
    return vals

def op_split(records, spec):
    # split[(field)] [on "sep"] [as name]
    rest=spec[len('split'):].strip()
    input_field=None; sep=','; out_field=None
    if rest.startswith('('):
        j=rest.find(')')
        input_field=rest[1:j].strip(); rest=rest[j+1:].strip()
    m=re.search(r'\bon\s+"((?:\\.|[^"])*)"', rest, re.I)
    if m:
        sep=unquote('"'+m.group(1)+'"')
        rest=(rest[:m.start()] + rest[m.end():]).strip()
    m=re.search(r'\bas\s+(.+)$', rest, re.I)
    if m:
        out_field=parse_field_name(m.group(1).strip())
    if out_field is None:
        out_field=input_field or '_split'
    out=[]
    for r in records:
        if input_field:
            if input_field not in r.fields:
                eprint(f'error: No value for key "{input_field}"'); continue
            src=r.fields[input_field]
            if not isinstance(src,str): src=legacy_value(src)
        else:
            src=r.raw
        nr=r.copy(); nr.fields[out_field]=split_csvish(src, sep); nr.raw_if_empty=False; out.append(nr)
    return out

def op_fields(records, spec):
    rest=spec[len('fields'):].strip()
    mode='only'
    low=rest.lower()
    if low.startswith('only '): rest=rest[5:].strip(); mode='only'
    elif low.startswith('except '): rest=rest[7:].strip(); mode='except'
    elif rest.startswith('+'): rest=rest[1:].strip(); mode='only'
    elif rest.startswith('-'): rest=rest[1:].strip(); mode='except'
    names=[parse_field_name(x.strip()) for x in split_top_level(rest, ',') if x.strip()]
    # fields nested.x keeps/removes top-level nested
    bases=[n.split('.')[0] if not n.startswith('["') else n for n in names]
    out=[]
    for r in records:
        nr=r.copy(); nr.raw_if_empty=False
        if mode=='only':
            nr.fields={k:v for k,v in r.fields.items() if k in bases}
        else:
            nr.fields={k:v for k,v in r.fields.items() if k not in bases}
        out.append(nr)
    return out

def op_where(records, expr_s):
    expr=ExprParser(expr_s).parse(); out=[]
    for r in records:
        try:
            if truthy(expr.eval(r, {'missing_none':False})):
                out.append(r)
        except Exception as e:
            eprint(f'error: {e}')
    return out

def op_expr(records, expr_s, name):
    expr=ExprParser(expr_s).parse(); out=[]; fname=parse_field_name(name)
    for r in records:
        nr=r.copy()
        try:
            nr.fields[fname]=expr.eval(nr, {'missing_none':False})
            nr.raw_if_empty=False
            out.append(nr)
        except Exception as e:
            eprint(f'error: {e}')
    return out

def parse_duration(s):
    m=re.fullmatch(r'([+-]?\d+(?:\.\d+)?)(ns|us|ms|s|m|h|d|w)', s.strip())
    if not m: raise EvalError(f'Invalid duration {s}')
    n=float(m.group(1)); unit=m.group(2)
    mult={'ns':1e-9,'us':1e-6,'ms':1e-3,'s':1,'m':60,'h':3600,'d':86400,'w':604800}[unit]
    return n*mult

def op_timeslice(records, spec):
    m=re.match(r'timeslice\((.*)\)\s+(\S+)(?:\s+as\s+(.+))?$', spec, re.I|re.S)
    if not m: raise ParseError('Invalid timeslice')
    expr=ExprParser(m.group(1).strip()).parse(); dur=parse_duration(m.group(2)); fname=parse_field_name((m.group(3) or '_timeslice').strip())
    out=[]
    for r in records:
        nr=r.copy()
        try:
            v=expr.eval(nr, {'missing_none':False})
            if not isinstance(v, DateVal): raise EvalError('Expected date')
            ts=v.dt.timestamp(); floored=math.floor(ts/dur)*dur
            nr.fields[fname]=DateVal(datetime.fromtimestamp(floored, tz=timezone.utc))
            nr.raw_if_empty=False; out.append(nr)
        except Exception as e:
            eprint(f'error: {e}')
    return out

def op_total(records, spec):
    m=re.match(r'total\((.*)\)(?:\s+as\s+(.+))?$', spec, re.I|re.S)
    if not m: raise ParseError('Invalid total')
    expr=ExprParser(m.group(1).strip()).parse(); fname=parse_field_name((m.group(2) or '_total').strip())
    total=0; out=[]
    for r in records:
        nr=r.copy()
        try:
            v=expr.eval(nr, {'missing_none':True})
            nv=maybe_number(v)
            if nv is not None: total += nv
        except Exception:
            pass
        nr.fields[fname]=total; nr.raw_if_empty=False; out.append(nr)
    return out

# ---------------- aggregations and sorting ----------------

@dataclass
class AggSpec:
    kind: str
    expr_s: str=None
    expr: object=None
    out: str=None
    pct: int=None

class AggState:
    def __init__(self, specs):
        self.specs=specs
        self.count=0
        self.cond_counts=[0]*len(specs)
        self.sums=[0]*len(specs)
        self.nums=[[] for _ in specs]
        self.distinct=[set() for _ in specs]
    def add(self, rec):
        self.count += 1
        for i,sp in enumerate(self.specs):
            if sp.kind=='count':
                if sp.expr is None:
                    self.cond_counts[i]+=1
                else:
                    try:
                        if truthy(sp.expr.eval(rec, {'missing_none':True})):
                            self.cond_counts[i]+=1
                    except Exception:
                        pass
            elif sp.kind in ('sum','average','min','max','pct'):
                try: v=sp.expr.eval(rec, {'missing_none':True})
                except Exception: v=None
                nv=maybe_number(v)
                if nv is not None:
                    if isinstance(nv,float) and math.isnan(nv): continue
                    if sp.kind=='sum': self.sums[i]+=nv
                    else: self.nums[i].append(nv)
            elif sp.kind=='count_distinct':
                try: v=sp.expr.eval(rec, {'missing_none':True})
                except Exception: v=None
                self.distinct[i].add(hashable_value(v))
    def result(self, i):
        sp=self.specs[i]
        if sp.kind=='count': return self.cond_counts[i]
        if sp.kind=='sum': return self.sums[i]
        vals=self.nums[i]
        if sp.kind=='average':
            return (sum(vals)/len(vals)) if vals else float('nan')
        if sp.kind=='min': return min(vals) if vals else None
        if sp.kind=='max': return max(vals) if vals else None
        if sp.kind=='pct':
            if not vals: return None
            vals=sorted(vals)
            idx=max(0, min(len(vals)-1, math.ceil(sp.pct/100.0*len(vals))-1))
            return vals[idx]
        if sp.kind=='count_distinct': return len(self.distinct[i])
        return None

def hashable_value(v):
    if isinstance(v, list): return tuple(hashable_value(x) for x in v)
    if isinstance(v, dict): return tuple((k,hashable_value(v[k])) for k in sorted(v.keys(), key=str))
    if isinstance(v, DateVal): return ('date', v.dt.timestamp())
    return v

def parse_agg_spec(part):
    expr_part, alias=split_as(part)
    p=expr_part.strip()
    low=p.lower()
    if low == 'count':
        return AggSpec('count', out=alias or '_count')
    m=re.match(r'count\((.*)\)$', p, re.I|re.S)
    if m:
        return AggSpec('count', expr_s=m.group(1).strip(), expr=ExprParser(m.group(1).strip()).parse(), out=alias or '_count')
    m=re.match(r'(sum|min|max|average|avg|count_distinct)\((.*)\)$', p, re.I|re.S)
    if m:
        name=m.group(1).lower(); exprs=m.group(2).strip()
        kind='average' if name=='avg' else name
        default={'sum':'_sum','min':'_min','max':'_max','average':'_average','count_distinct':'_countDistinct'}[kind]
        return AggSpec(kind, expr_s=exprs, expr=ExprParser(exprs).parse(), out=alias or default)
    m=re.match(r'(?:pct|p)(\d+)\((.*)\)$', p, re.I|re.S)
    if m:
        pct=int(m.group(1)); exprs=m.group(2).strip()
        return AggSpec('pct', expr_s=exprs, expr=ExprParser(exprs).parse(), out=alias or f'p{pct}', pct=pct)
    return None

def is_aggregate_segment(seg):
    left=seg
    pos=find_top_level_word(seg, 'by')
    if pos: left=seg[:pos[0]]
    parts=split_top_level(left, ',')
    return bool(parts) and all(parse_agg_spec(p) is not None for p in parts if p.strip())

def op_aggregate(records, seg):
    pos=find_top_level_word(seg, 'by')
    if pos:
        left=seg[:pos[0]].strip(); bys=seg[pos[1]:].strip()
    else:
        left=seg.strip(); bys=''
    specs=[parse_agg_spec(p) for p in split_top_level(left, ',') if p.strip()]
    group_exprs=[]; group_names=[]
    if bys:
        for g in split_top_level(bys, ','):
            g=g.strip(); group_names.append(g); group_exprs.append(ExprParser(g).parse())
    groups=OrderedDict()
    for r in records:
        key=[]
        for ex in group_exprs:
            try: key.append(ex.eval(r, {'missing_none':True}))
            except Exception: key.append(None)
        h=tuple(hashable_value(x) for x in key)
        if h not in groups:
            groups[h]=(key,AggState(specs))
        groups[h][1].add(r)
    rows=[]; columns=list(group_names)+[sp.out for sp in specs]
    for key,state in groups.values():
        fields=OrderedDict()
        for n,v in zip(group_names,key): fields[n]=v
        for i,sp in enumerate(specs): fields[sp.out]=state.result(i)
        rows.append(Record('', fields, False))
    # default sort by first aggregate desc, then groups ascending
    if specs and rows:
        first=specs[0].out
        def sort_key(r):
            return r.fields.get(first)
        rows.sort(key=lambda r: SortWrapper(r.fields.get(first), desc=True))
        # stable tie sort by group fields ascending after primary: use comparator via cmp_to_key for accuracy
        from functools import cmp_to_key
        def cmp(a,b):
            c=cmp_values_for_sort(a.fields.get(first), b.fields.get(first), desc=True)
            if c: return c
            for g in group_names:
                c=cmp_values_for_sort(a.fields.get(g), b.fields.get(g), desc=False)
                if c: return c
            return 0
        rows.sort(key=cmp_to_key(cmp))
    return rows, columns, True

class SortWrapper:
    def __init__(self,v,desc=False): self.v=v; self.desc=desc
    def __lt__(self,other):
        c=cmp_values(self.v, other.v)
        return c>0 if self.desc else c<0

def cmp_values_for_sort(a,b,desc=False):
    # NaN sorts high for descending, low for ascending.
    c=cmp_values(a,b)
    if desc: c=-c
    return c

def parse_sort_specs(rest):
    parts=split_top_level(rest, ',')
    specs=[]; last_dir=None
    for p in parts:
        p=p.strip(); direction=None
        m=re.search(r'\s+(asc|desc)\s*$', p, re.I)
        if m:
            direction=m.group(1).lower(); p=p[:m.start()].strip(); last_dir=direction
        specs.append([p,direction])
    if last_dir:
        for sp in specs:
            if sp[1] is None: sp[1]=last_dir
    for sp in specs:
        if sp[1] is None: sp[1]='asc'
    return [(ExprParser(expr).parse(), expr, direction) for expr,direction in specs if expr]

def op_sort(records, seg, columns=None):
    m=re.match(r'sort\s+by\s+(.+)$', seg, re.I|re.S)
    if not m: raise ParseError('Invalid sort')
    specs=parse_sort_specs(m.group(1).strip())
    from functools import cmp_to_key
    def cmp(a,b):
        for ex,txt,dirn in specs:
            try: av=ex.eval(a, {'missing_none':True})
            except Exception: av=None
            try: bv=ex.eval(b, {'missing_none':True})
            except Exception: bv=None
            c=cmp_values(av,bv)
            if dirn=='desc': c=-c
            if c: return c
        return 0
    rows=list(records)
    rows.sort(key=cmp_to_key(cmp))
    if columns is None:
        columns=union_columns(rows)
    return rows, columns, True

# ---------------- rendering ----------------

def union_columns(records):
    order=[]; seen=set()
    for r in records:
        for k in sorted(r.fields.keys(), key=str):
            if k not in seen:
                seen.add(k); order.append(k)
    return order

def render_legacy_rows(records):
    # First collect columns in first-appearance order (each record's keys sorted).
    cols=union_columns(records)
    widths={}
    for c in cols:
        max_len=0
        for r in records:
            if c in r.fields:
                cell=f'[{c}={legacy_value(r.fields[c])}]'
                max_len=max(max_len, len(cell))
        widths[c]=max(max_len+8, 2*len(str(c))+11)
    lines=[]
    for r in records:
        if not r.fields:
            if r.raw_if_empty:
                lines.append(r.raw)
            continue
        present=[i for i,c in enumerate(cols) if c in r.fields]
        if not present:
            continue
        start=min(present); end=max(present); s=[]
        for i in range(start,end+1):
            c=cols[i]; w=widths[c]
            if c in r.fields:
                cell=f'[{c}={legacy_value(r.fields[c])}]'
                if i<end:
                    s.append(cell + ' ' * max(0, w-len(cell)))
                else:
                    s.append(cell)
            else:
                if i<end:
                    s.append(' ' * w)
        lines.append(''.join(s).rstrip())
    return '\n'.join(lines) + ('\n' if lines else '')

def render_table(records, columns, mode):
    if mode=='json':
        arr=[]
        for r in records:
            arr.append(OrderedDict((c,jsonable(r.fields.get(c))) for c in columns if c in r.fields))
        return json.dumps(arr, separators=(',', ':'), ensure_ascii=False) + '\n'
    if mode=='logfmt':
        lines=[]
        for r in records:
            keys=sorted(r.fields.keys(), key=str)
            if not keys: continue
            lines.append(' '.join(f'{k}={legacy_value(r.fields[k])}' for k in keys))
        return '\n'.join(lines)+('\n' if lines else '')
    if mode.startswith('format='):
        fmt=mode[len('format='):]
        return render_format(records, fmt)
    if not records:
        return 'No data\n'
    widths=[]
    for c in columns:
        max_len=len(str(c))
        for r in records:
            max_len=max(max_len, len(legacy_value(r.fields.get(c))))
        widths.append(max_len+8)
    header=''.join(str(c).ljust(widths[i]) if i<len(columns)-1 else str(c) for i,c in enumerate(columns)).rstrip()
    sep='-'*sum(widths)
    lines=[header, sep]
    for r in records:
        parts=[]
        for i,c in enumerate(columns):
            val=legacy_value(r.fields.get(c))
            if i<len(columns)-1: parts.append(val.ljust(widths[i]))
            else: parts.append(val)
        lines.append(''.join(parts).rstrip())
    return '\n'.join(lines)+'\n'

def render_json_lines(records):
    lines=[]
    for r in records:
        if not r.fields:
            if r.raw_if_empty:
                lines.append(r.raw)
            continue
        lines.append(dumps_json_obj(r.fields))
    return '\n'.join(lines)+('\n' if lines else '')

def render_logfmt(records):
    lines=[]
    for r in records:
        if not r.fields:
            if r.raw_if_empty: lines.append(r.raw)
            continue
        keys=sorted(r.fields.keys(), key=str)
        if not keys: continue
        lines.append(' '.join(f'{k}={legacy_value(r.fields[k])}' for k in keys))
    return '\n'.join(lines)+('\n' if lines else '')

def render_format(records, fmt):
    lines=[]
    for r in records:
        lines.append(apply_format(fmt, r.fields))
    return '\n'.join(lines)+('\n' if lines else '')

def apply_format(fmt, fields):
    out=[]; i=0; n=len(fmt)
    while i<n:
        if fmt[i]=='{' and i+1<n and fmt[i+1]=='{': out.append('{'); i+=2; continue
        if fmt[i]=='}' and i+1<n and fmt[i+1]=='}': out.append('}'); i+=2; continue
        if fmt[i]=='{':
            j=fmt.find('}', i+1)
            if j==-1:
                out.append(fmt[i]); i+=1; continue
            key=fmt[i+1:j]
            # ignore format spec after colon
            key=key.split(':',1)[0]
            out.append(legacy_value(fields.get(key)))
            i=j+1; continue
        out.append(fmt[i]); i+=1
    return ''.join(out)

# ---------------- aliases ----------------

def load_aliases(alias_dir=None, no_alias=False):
    if no_alias: return {}
    dirs=[]
    if alias_dir: dirs=[alias_dir]
    else:
        cur=os.getcwd()
        while True:
            d=os.path.join(cur,'.agrind-aliases')
            if os.path.isdir(d): dirs.append(d)
            parent=os.path.dirname(cur)
            if parent==cur: break
            cur=parent
    aliases={}
    for d in dirs:
        try: files=[os.path.join(d,x) for x in os.listdir(d)]
        except Exception: continue
        for path in files:
            if not os.path.isfile(path): continue
            try: txt=open(path,encoding='utf-8').read()
            except Exception: continue
            km=re.search(r'keyword\s*=\s*"([^"]+)"', txt)
            tm=re.search(r'template\s*=\s*"""(.*?)"""', txt, re.S)
            if not tm: tm=re.search(r'template\s*=\s*"((?:\\.|[^"])*)"', txt, re.S)
            if km and tm:
                val=tm.group(1)
                if not '"""' in tm.group(0): val=unquote('"'+val+'"')
                aliases[km.group(1)]=val.strip()
    return aliases

def expand_alias_ops(ops, aliases):
    if not aliases: return ops
    changed=True
    while changed:
        changed=False; new=[]
        for op in ops:
            key=op.strip()
            if key in aliases:
                parts=split_pipeline(aliases[key])
                # alias template might include a filter at front; if first piece is a filter without operator, include remaining ops.
                for p in parts:
                    if p.strip(): new.append(p.strip())
                changed=True
            else:
                new.append(op)
        ops=new
    return ops

# ---------------- query execution ----------------

def apply_operator(records, op, state):
    seg=op.strip()
    low=seg.lower()
    if not seg: return records
    if low == 'json' or low.startswith('json '):
        from_field=None
        m=re.match(r'json\s+from\s+(.+)$', seg, re.I)
        if m: from_field=parse_field_name(m.group(1).strip())
        return op_json(records, from_field)
    if low == 'logfmt' or low.startswith('logfmt '):
        from_field=None
        m=re.match(r'logfmt\s+from\s+(.+)$', seg, re.I)
        if m: from_field=parse_field_name(m.group(1).strip())
        return op_logfmt(records, from_field)
    if low.startswith('parse regex'):
        return op_parse_regex(records, seg)
    if low.startswith('parse '):
        return op_parse(records, seg)
    if low.startswith('split'):
        return op_split(records, seg)
    if low.startswith('fields'):
        return op_fields(records, seg)
    if low.startswith('where '):
        return op_where(records, seg[6:].strip())
    if low.startswith('limit '):
        try: n=int(seg[6:].strip())
        except Exception: raise ParseError(f'Invalid limit')
        if n==0: raise ParseError('Limit must be a non-zero integer, found 0')
        return records[:n] if n>0 else records[n:]
    if low.startswith('timeslice'):
        return op_timeslice(records, seg)
    if low.startswith('total'):
        return op_total(records, seg)
    if low.startswith('sort by'):
        rows, cols, table = op_sort(records, seg, state.get('columns'))
        state['columns']=cols; state['table']=True
        return rows
    if is_aggregate_segment(seg):
        rows, cols, table = op_aggregate(records, seg)
        state['columns']=cols; state['table']=True
        return rows
    expr_s, name=split_as(seg)
    if name:
        return op_expr(records, expr_s, name)
    # Unknown bare operator is a parse error.
    raise ParseError('Expected an operator')

def execute_query(query, lines, aliases=None):
    parts=split_pipeline(query)
    if not parts:
        raise ParseError('MissingQuery')
    filter_part=parts[0].strip() or '*'
    ops=[p.strip() for p in parts[1:]]
    ops=expand_alias_ops(ops, aliases or {})
    filt=FilterParser(filter_part).parse()
    records=[]
    for line in lines:
        if line.endswith('\n'): line=line[:-1]
        if line.endswith('\r'): line=line[:-1]
        if filt.match(line): records.append(Record(line))
    state={'table':False, 'columns':None}
    for op in ops:
        records=apply_operator(records, op, state)
    return records, state

# ---------------- CLI ----------------

def parse_cli(argv):
    opts={'file':None,'output':'legacy','alias_dir':None,'no_alias':False}
    query=[]; i=0
    while i<len(argv):
        a=argv[i]
        if a=='--':
            query += argv[i+1:]; break
        if a in ('-h','--help'):
            print(HELP_SHORT if a=='-h' else HELP_LONG, end=''); sys.exit(0)
        if a in ('-V','--version'):
            print(VERSION); sys.exit(0)
        if a in ('-f','--file'):
            i+=1
            if i>=len(argv):
                eprint("error: a value is required for '--file <FILE>'"); sys.exit(2)
            opts['file']=argv[i]
        elif a.startswith('--file='):
            opts['file']=a.split('=',1)[1]
        elif a in ('-o','--output'):
            i+=1
            if i>=len(argv): eprint("error: a value is required for '--output <OUTPUT>'"); sys.exit(2)
            opts['output']=a_out=argv[i]
        elif a.startswith('--output='):
            opts['output']=a.split('=',1)[1]
        elif a in ('-m','--format'):
            i+=1
            if i>=len(argv): eprint("error: a value is required for '--format <FORMAT>'"); sys.exit(2)
            opts['output']='format='+argv[i]
        elif a.startswith('--format='):
            opts['output']='format='+a.split('=',1)[1]
        elif a in ('-a','--alias-dir'):
            i+=1
            if i>=len(argv): eprint("error: a value is required for '--alias-dir <ALIAS_DIR>'"); sys.exit(2)
            opts['alias_dir']=argv[i]
        elif a.startswith('--alias-dir='):
            opts['alias_dir']=a.split('=',1)[1]
        elif a=='--no-alias':
            opts['no_alias']=True
        elif a.startswith('-'):
            eprint(f"error: unexpected argument '{a}' found\n")
            eprint(f"  tip: to pass '{a}' as a value, use '-- {a}'\n")
            eprint("Usage: executable [OPTIONS] [QUERY]\n")
            eprint("For more information, try '--help'.")
            sys.exit(2)
        else:
            query.append(a)
        i+=1
    if len(query)>1:
        eprint(f"error: unexpected argument '{query[1]}' found\n")
        eprint("Usage: executable [OPTIONS] [QUERY]\n")
        eprint("For more information, try '--help'.")
        sys.exit(2)
    opts['query']=query[0] if query else None
    return opts

def main(argv=None):
    argv=sys.argv[1:] if argv is None else argv
    opts=parse_cli(argv)
    if opts['query'] is None:
        eprint('Error: MissingQuery'); return 1
    outmode=opts['output']
    if not (outmode in ('legacy','json','logfmt') or outmode.startswith('format=')):
        eprint(f'Error: InvalidOutputMode {{ choice: "{outmode}", choices: "legacy, json, logfmt, format" }}')
        return 1
    try:
        if opts['file']:
            with open(opts['file'], 'r', encoding='utf-8', errors='replace') as f: lines=f.readlines()
        else:
            lines=sys.stdin.readlines()
    except OSError as e:
        eprint(f'Error: Os {{ code: {e.errno}, kind: NotFound, message: "{e.strerror}" }}')
        return 1
    try:
