            eprint('Error: Failed to parse query')
        elif msg=='MissingQuery':
            eprint('Error: MissingQuery')
        else:
            eprint(f'Error: {msg}')
        return 1
    if state.get('table'):
        output=render_table(records, state.get('columns') or union_columns(records), outmode)
